storage_test_config <- function(profile="smoke") list(project=list(profile=profile,dataset_id="era5_mintemp"),paths=list(root=NULL))
test_that("storage profiles are isolated", { root<-file.path("D:/tmp","cds-datagrab"); s<-resolve_storage_paths(storage_test_config("smoke"),getwd(),root); p<-resolve_storage_paths(storage_test_config("production"),getwd(),root); expect_false(identical(s$dataset_root,p$dataset_root)); expect_true(grepl("data/smoke/era5_mintemp/daily$",s$daily_dir)); expect_true(grepl("data/production/era5_mintemp/weekly$",p$weekly_dir)); expect_false(file.exists(s$root_marker)) })
test_that("storage marker and directories are created safely", { root<-file.path("D:/tmp",paste0("test-storage-",as.integer(Sys.time()))); s<-resolve_storage_paths(storage_test_config(),getwd(),root,create=TRUE); expect_true(file.exists(s$root_marker)); expect_true(dir.exists(s$daily_dir)); expect_true(assert_storage_target(s$daily_dir,s)); bad<-s; jsonlite::write_json(list(application="wrong"),s$root_marker,auto_unbox=TRUE); expect_error(assert_storage_target(s$daily_dir,bad),"marker") })
test_that("unsafe roots are rejected", { expect_error(resolve_storage_paths(storage_test_config(),getwd(),"/")); expect_error(resolve_storage_paths(storage_test_config(),getwd(),"/project/disease_ecology/NWScrewworm/data")); expect_error(resolve_storage_paths(storage_test_config(),getwd(),"../outside")) })
test_that("explicit repository, child, and spatial roots are rejected", { repo<-normalizePath(getwd(),winslash="/",mustWork=TRUE); expect_error(resolve_storage_paths(storage_test_config(),repo,repo),"Repository root|outside the repository checkout"); expect_error(resolve_storage_paths(storage_test_config(),repo,file.path(repo,"child-output")),"outside the repository checkout"); expect_error(resolve_storage_paths(storage_test_config(),repo,file.path(repo,"spatial_domain")),"outside the repository checkout") })
test_that("variable-specific roots cannot be shared", { root<-file.path("D:/tmp",paste0("variable-root-",as.integer(Sys.time()))); lai<-storage_test_config(); lai$project$dataset_id<-"era5_lai_low"; rh<-storage_test_config(); rh$project$dataset_id<-"agera5_relhum_min"; resolve_storage_paths(lai,getwd(),root,create=TRUE); expect_error(resolve_storage_paths(rh,getwd(),root,create=TRUE),"already belongs to variable") })
test_that("external roots remain valid for mintemp and soil moisture", { mint<-resolve_storage_paths(storage_test_config(),getwd(),file.path("D:/tmp","mintemp-external")); soil<-storage_test_config(); soil$project$dataset_id<-"era5_soilmoist"; soil_root<-resolve_storage_paths(soil,getwd(),file.path("D:/tmp","soilmoist-external")); expect_true(grepl("mintemp-external",mint$root)); expect_true(grepl("soilmoist-external",soil_root$root)) })
